  setBusy(false);if(result.error){notify('Reaction failed: '+result.error.message);return}setMyLikes(v=>({...v,[post.id]:!liked}));setPosts(v=>v.map(p=>p.id===post.id?{...p,likes:Math.max(0,p.likes+(liked?-1:1))}:p));
